insert into public.species (id, slug, name, blurb, home_land_id, art_base_path, base_hue, sort_order) select 'b0000000-0000-4000-8000-000000000009', 'glacibun', 'Glacibun', 'A round icy-blue companion with cloud-soft fur, long ears, and a crystal horn. It likes wind-bells and the cold edge of the shoals.', id, 'art/species/glacibun.png', 200, 9 from public.lands where slug = 'silvershoal';
insert into public.species (id, slug, name, blurb, home_land_id, art_base_path, base_hue, sort_order) select 'b0000000-0000-4000-8000-000000000010', 'mosscrag', 'Mosscrag', 'A stack of grey stones that learned to smile, with moss in the cracks and tiny flowers on top. Patient, and happiest in the shade.', id, 'art/species/mosscrag.png', 78, 10 from public.lands where slug = 'mossglen';
insert into public.species (id, slug, name, blurb, home_land_id, art_base_path, base_hue, sort_order) select 'b0000000-0000-4000-8000-000000000011', 'tidewing', 'Tidewing', 'A teal flyer with wide gentle wings and a curl of a tail. It skims the pools and rarely hurries.', id, 'art/species/tidewing.png', 178, 11 from public.lands where slug = 'silvershoal';
insert into public.species (id, slug, name, blurb, home_land_id, art_base_path, base_hue, sort_order) select 'b0000000-0000-4000-8000-000000000012', 'cogwhisk', 'Cogwhisk', 'A copper clockwork companion with bright eyes, curled whiskers, and a gear at the tail. Precise, curious, and proud of its tick.', id, 'art/species/cogwhisk.png', 28, 12 from public.lands where slug = 'harborlight';
insert into public.species (id, slug, name, blurb, home_land_id, art_base_path, base_hue, sort_order) select 'b0000000-0000-4000-8000-000000000013', 'bramblebuzz', 'Bramblebuzz', 'A black-and-honey bee-bear with a comb belly and small glass wings. Busy, sweet-tempered, and full of pollen gossip.', id, 'art/species/bramblebuzz.png', 42, 13 from public.lands where slug = 'mossglen';
insert into public.species (id, slug, name, blurb, home_land_id, art_base_path, base_hue, sort_order) select 'b0000000-0000-4000-8000-000000000014', 'dunesprout', 'Dunesprout', 'A sandy companion with a striped tail and a crown of warm flowers. Sun-sleepy, and fond of cliff gardens.', id, 'art/species/dunesprout.png', 32, 14 from public.lands where slug = 'cinderreach';
insert into public.species (id, slug, name, blurb, home_land_id, art_base_path, base_hue, sort_order) select 'b0000000-0000-4000-8000-000000000015', 'silkmoth', 'Silkmoth', 'A white fluff of a moth with navy wings patterned in moons. Soft-voiced, and awake when the quay lamps come on.', id, 'art/species/silkmoth.png', 222, 15 from public.lands where slug = 'harborlight';
insert into public.species (id, slug, name, blurb, home_land_id, art_base_path, base_hue, sort_order) select 'b0000000-0000-4000-8000-000000000016', 'berrybop', 'Berrybop', 'A raspberry-round companion with a leafy cap and a jam-bright smile. Eager, and easy to please.', id, 'art/species/berrybop.png', 352, 16 from public.lands where slug = 'mossglen';
insert into public.species (id, slug, name, blurb, home_land_id, art_base_path, base_hue, sort_order) select 'b0000000-0000-4000-8000-000000000017', 'stormuff', 'Stormuff', 'A dark cloud companion stitched with blue lightning. It rumbles, but the thunder is mostly for show.', id, 'art/species/stormuff.png', 208, 17 from public.lands where slug = 'cinderreach';
insert into public.species (id, slug, name, blurb, home_land_id, art_base_path, base_hue, sort_order) select 'b0000000-0000-4000-8000-000000000018', 'rubyclaw', 'Rubyclaw', 'A red crab with ruby claws and a small shell crown. Proud of its pinch, and gentler than it looks.', id, 'art/species/rubyclaw.png', 355, 18 from public.lands where slug = 'cinderreach';
